                size="icon"
                onClick={onCopy}
                className={cn(
                  "absolute right-2 top-2 size-8 transition-all duration-200",
                  isCopied
                    ? "bg-green-100 text-green-600 hover:bg-green-100"
                    : "hover:bg-background"
                )}
                aria-label={isCopied ? "Copied!" : "Copy to clipboard"}
